sys_script_include.script:
var OD_Map = Class.create();
OD_Map.prototype = {
    initialize: function() {
    },
	/* OpenData statusId -> ServiceNow incident state, for u_od_state.
     * Many-to-one and deliberately banded: a future OpenData release adding
     * a new hold or closure reason lands in the right bucket automatically. */
    statusIdToState: function (statusId) {
        var s = parseInt(statusId, 10);
        if (isNaN(s))     return null;
        if (s === 1)      return 1;   // New
        if (s === 120)    return 6;   // Solved pending confirmation -> Resolved
        if (s === 1003)   return 8;   // Errant entry -> Canceled
        if (s >= 1000)    return 7;   // 1000, 1001, 1002, 1004 -> Closed
        if (s >= 900)     return 3;   // 900-905 -> On Hold
        return 2;                 // 100, 110, 200-204 -> In Progress
    },

    /* ServiceNow incident state -> canonical OpenData statusId.
     * LOSSY INVERSE. Only call this when the state actually changed —
     * see the trap in section 11. */
    stateToCanonicalStatusId: function (state, closeCode) {
        switch (parseInt(state, 10)) {
            case 1:  return 1;
            case 2:  return 100;
            case 3:  return 900;
            case 6:  return 120;
            case 7:  return this._closeCodeToStatusId(closeCode);
            case 8:  return 1003;
            default: return null;
        }
    },

    /* Never returns 1000 — OpenData rejects the bare CLOSED status on write. */
    _closeCodeToStatusId: function (closeCode) {
        var c = String(closeCode || '').toLowerCase();
        if (c.indexOf('not solved') >= 0 || c.indexOf('not resolved') >= 0) return 1002;
        return 1001;
    },

    urgencyToLevelId: function (urgency) {
        switch (parseInt(urgency, 10)) {
            case 1:  return 30;   // High
            case 2:  return 20;   // Medium
            case 3:  return 10;   // Low
            default: return null;
        }
    },

    isTerminal: function (statusId) {
        return parseInt(statusId, 10) >= 1000;
    },

    /* GlideDateTime -> yyyy-MM-ddTHH:mm:ss+00:00, the DTZ form OpenData parses.
     * getValue() is already UTC, so the offset is always +00:00. Emitting an
     * explicit offset matters: the offsetless form is reinterpreted in the
     * OpenData server's own timezone. */
    toDTZ: function (gdt) {
        if (!gdt || gdt.nil()) return null;
        return new GlideDateTime(gdt.toString()).getValue().replace(' ', 'T') + '+00:00';
    },

    type: 'OD_Map'
};
